def area(width, height=1):
    return width * height
print(area(3, 4))  # 12
print(area(5))  # 5
# min and max are built in: smallest and largest item.
def min_max(nums):
    return min(nums), max(nums)
print(min_max([4, 1, 9]))  # (1, 9)
low, high = min_max([4, 1, 9])
print(low, high)  # 1 9

